/**
 * Generated alongside `brief.parser.js`: one numeric constant per named term.
 *
 * Only the terms the external tokenizer needs are declared here. Adding an
 * `@external tokens` term to the grammar means adding it here too, or `tokens.ts` will
 * not compile — which is the point.
 */
export declare const Frontmatter: number;
export declare const virtualNewline: number;
